/**
 * Every character has a headshot (David, 2026-11-03: "a bunch of people made characters with no portraits … it needs to be
 * generated by default as a requirement"). Until now a portrait came only from the web builder's looks picks, so a
 * character made by an agent (MCP), by the API, or on the web without picking looks had none until someone drew one.
 *
 * - **On creation:** schedulePortrait, after the response, for every new character (app/api/characters/route.ts).
 * - **Backstop:** portraitSweep, a few at a time on the hourly lobby job, for whoever still has none (every character
 *   made before this, and any whose draw failed).
 * - **Which model:** a character with looks picked is drawn from them on our fal key, Hive-screened, free to them
 *   (lib/looks-draw.ts drawLooksPortrait, capped per day). Anyone else, or a looks draw that was refused or over its cap, gets the
 *   show's own: Venice safe mode from their written look or bio, PG-checked (lib/agent-portraits.ts drawShowPortrait).
 * - **Never replaces:** a character with any portrait is left alone, and their creator can still draw another.
 *
 * DEFAULT_PORTRAITS=0 turns it off. Tests leave it off unless one turns it on (setDefaultPortraitsForTests).
 */
import type { Db } from "./db";
import { drawShowPortrait, portraitTargets } from "./agent-portraits";
import { drawLooksPortrait } from "./looks-draw";
import { DELETED_OWNER } from "./rules";

/** How many a sweep draws; the lobby job runs hourly. */
export const PORTRAIT_SWEEP = 4;

let forTests: boolean | null = null;
/** Tests don't draw portraits unless one asks (true), and put it back with null. */
export function setDefaultPortraitsForTests(on: boolean | null): void {
  forTests = on;
}

export function defaultPortraitsEnabled(env: Record<string, string | undefined> = process.env): boolean {
  if (forTests !== null) return forTests;
  if (env.NODE_ENV === "test" || env.VITEST) return false;
  return env.DEFAULT_PORTRAITS !== "0";
}

export type EnsureResult = "has" | "looks" | "show" | { failed: string };

/** One character's headshot: nothing if they have one, else drawn from their looks, else the show's own. Never throws. */
export async function ensurePortrait(db: Db, characterId: string): Promise<EnsureResult> {
  try {
    const c = (
      await db.query<{ owner_id: string | null; has: boolean; gender: string | null }>(
        `select ch.owner_id, ch.extras #>> '{looks,gender}' as gender,
                exists (select 1 from character_assets a where a.character_id = ch.id and a.kind = 'portrait') as has
           from characters ch where ch.id = $1`,
        [characterId],
      )
    ).rows[0];
    if (!c) return { failed: "no such character" };
    if (c.has) return "has";
    if (c.owner_id === DELETED_OWNER) return { failed: "taken off the show" };
    if (c.gender) {
      const r = await drawLooksPortrait(db, characterId);
      if (r.ok) return "looks";
    }
    const shown = await drawShowPortrait(db, characterId);
    return shown.ok ? "show" : { failed: shown.reason };
  } catch (err) {
    return { failed: err instanceof Error ? err.message.slice(0, 160) : "error" };
  }
}

/** A new character's headshot, after the response so a save never waits on a picture. Best effort. */
export async function schedulePortrait(db: Db, characterId: string): Promise<void> {
  if (!defaultPortraitsEnabled()) return;
  const run = () =>
    ensurePortrait(db, characterId)
      .then((r) => {
        if (typeof r === "object") console.error("[portrait] not drawn", characterId, r.failed);
      })
      .catch(() => undefined);
  const { inlineGenerationEnabled } = await import("./jobs");
  if (inlineGenerationEnabled()) return run();
  try {
    const { after } = await import("next/server");
    after(run);
  } catch {
    await run();
  }
}

/** The next few characters with no headshot, drawn. Returns how many got one and how many are still waiting. */
export async function portraitSweep(db: Db, size = PORTRAIT_SWEEP): Promise<{ drawn: number; failed: number; left: number }> {
  if (!defaultPortraitsEnabled()) return { drawn: 0, failed: 0, left: 0 };
  const todo = await portraitTargets(db, size, { all: true });
  const results = await Promise.all(todo.map((id) => ensurePortrait(db, id)));
  const drawn = results.filter((r) => r === "looks" || r === "show").length;
  return { drawn, failed: results.filter((r) => typeof r === "object").length, left: Math.max(0, (await portraitTargets(db, 1000, { all: true })).length) };
}
